changeSet.sql:
ALTER TABLE document.claims RENAME COLUMN document_id TO contract_id;
ALTER TABLE document.claims ADD COLUMN IF NOT EXISTS from_in TEXT;
ALTER TABLE document.claims ADD COLUMN IF NOT EXISTS to_in TEXT;

UPDATE document.claims c
   SET from_in = d.seller_in, to_in = d.buyer_in
  FROM document.contracts d
 WHERE d.id = c.contract_id;

ALTER TABLE document.claims DROP COLUMN IF EXISTS seller_id;
ALTER TABLE document.claims DROP COLUMN IF EXISTS buyer_id;
